from math import isqrt


def are_equivalent(a: int, b: int) -> bool:
    """Return whether two positive integers have equal sums of divisors."""
    def divisor_sum(n: int) -> int:
        if n <= 0:
            raise ValueError("Inputs must be positive integers.")

        total = 0
        for divisor in range(1, isqrt(n) + 1):
            if n % divisor == 0:
                total += divisor
                paired_divisor = n // divisor
                if paired_divisor != divisor:
                    total += paired_divisor
        return total

    return divisor_sum(a) == divisor_sum(b)
